// Shared price table. Source of truth: src/economy/prices.json ({ id: { price, cls, starter } }, generated by the
// economy workstream and used by the client too). Until it exists, prices fall back to the catalog price field and
// the class defaults of docs/ECONOMY.md, with the cheapest compact and the cheapest bicycle as starters.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
export const SELL_RATIO = 0.55;

const CLASS_RANGE = {
  bicycle: [150, 1200], small: [800, 4000], motorcycle: [800, 4000], compact: [9000, 18000], sedan: [18000, 45000], suv: [18000, 45000],
  pickup: [18000, 45000], van: [18000, 45000], coupe: [18000, 45000], classic: [18000, 45000], luxury: [45000, 150000], service: [40000, 160000],
  sports: [45000, 150000], muscle: [45000, 150000], super: [150000, 1500000], truck: [40000, 160000], bus: [40000, 160000],
  boat: [25000, 650000], heli: [450000, 2800000], plane: [280000, 6500000],
};

function nice(v) {
  if (v < 1000) return Math.round(v / 10) * 10;
  const p = 10 ** (Math.floor(Math.log10(v)) - 1);
  return Math.round(v / p) * p - (v >= 10000 ? 100 : 0);
}

/** Load prices: Map(id → { price, cls, starter }). */
export function loadPrices(vehicles, file = process.env.PRICES_PATH || path.resolve(here, '../../src/economy/prices.json'), log = console) {
  const out = new Map();
  let src = 'fallback';
  try {
    const raw = JSON.parse(fs.readFileSync(file, 'utf8'));
    const table = raw.prices || raw;
    for (const [id, e] of Object.entries(table)) {
      if (!e || !Number.isFinite(e.price)) continue;
      out.set(id, { price: Math.max(0, Math.round(e.price)), cls: String(e.cls || ''), starter: !!e.starter, traffic: Number.isFinite(e.traffic) ? e.traffic : 0 });
    }
    src = path.basename(file);
  } catch { /* fallback below */ }
  // fill gaps (and the whole table when prices.json is missing)
  const raw = vehicles.raw || [];
  for (const v of raw) {
    if (out.has(v.id)) continue;
    const cls = v.kind === 'bicycle' ? 'bicycle' : v.kind === 'heli' || v.kind === 'plane' || v.kind === 'boat' ? v.kind : v.category || v.kind;
    const r = CLASS_RANGE[cls] || CLASS_RANGE.sedan;
    const price = Number.isFinite(v.price) && v.price > 0 ? v.price : nice(r[0] + (r[1] - r[0]) * Math.pow(Math.max(0, Math.min(1, v.tier ?? 0.3)), 1.6));
    out.set(v.id, { price, cls, starter: false, traffic: v.traffic ? 0.5 : 0 });
  }
  if (![...out.values()].some((p) => p.starter)) {
    const cheapest = (pred) => [...out.entries()].filter(([id, p]) => pred(id, p)).sort((a, b) => a[1].price - b[1].price)[0];
    const kindOf = new Map(raw.map((v) => [v.id, v]));
    const c = cheapest((id, p) => p.cls === 'compact' || kindOf.get(id)?.category === 'compact');
    const b = cheapest((id) => kindOf.get(id)?.kind === 'bicycle');
    if (c) c[1].starter = true;
    if (b) b[1].starter = true;
  }
  log.info?.(`[prices] ${out.size} prices (${src}), starters: ${[...out].filter(([, p]) => p.starter).map(([id]) => id).join(', ')}`);
  return out;
}
